(function(api){const laneX=[18,168,318],fs=api.fs,basePath=api.basePath;let suitImages=[fs.readFileSync(basePath+"SUIT_S.IMG"),fs.readFileSync(basePath+"SUIT_H.IMG"),fs.readFileSync(basePath+"SUIT_D.IMG"),fs.readFileSync(basePath+"SUIT_C.IMG")];function cardRank(card){return card&15}function cardSuit(card){return card>>4&3}function rankText(rank){if(rank===1)return"A";if(rank===11)return"J";if(rank===12)return"Q";if(rank===13)return"K";if(rank===14)return"JK";return String(rank)}function suitText(suit){return suit===0?"S":suit===1?"H":suit===2?"D":"C"}function total(cards){let i=0,value=0,groupValue,rankValue;while(i<cards.length){rankValue=cards[i]&15;if(rankValue<=10){groupValue=rankValue;i++;while(i<cards.length&&(cards[i]&15)>10){if((cards[i]&15)===13)groupValue<<=1;i++}value+=groupValue}else i++}return value}function drawSuit(suit,x,y){if(suitImages[suit])h.drawImage(suitImages[suit],x,y)}function selector(x1,y1,x2,y2){h.drawRect(x1,y1,x2,y2).drawRect(x1+1,y1+1,x2-1,y2-1)}function bold(text,x,y,scale){h.setFont("6x8",scale).drawString(text,x,y).drawString(text,x+1,y)}function spacedBold(text,x,y,scale,align){const step=6*scale+1,width=text.length?text.length*step-1:0;let i,drawX=align===0?x-Math.floor(width/2):align===1?x-width:x;h.setFont("6x8",scale).setFontAlign(-1,-1);for(i=0;i<text.length;i++){h.drawString(text[i],drawX,y).drawString(text[i],drawX+1,y);drawX+=step}}function strong(text,x,y,scale){h.setFont("6x8",scale).drawString(text,x,y).drawString(text,x+1,y).drawString(text,x,y+1).drawString(text,x+1,y+1)}function miniCard(card,x,y){const rankValue=cardRank(card),suit=cardSuit(card),rankLabel=rankText(rankValue),sx=suit===0?21:23;h.setColor(3).drawRect(x,y,x+31,y+41).drawRect(x+1,y+1,x+30,y+40);strong(rankLabel,x+(rankLabel.length>1?2:3),y+3,1);if(rankValue===14){h.setFont("6x8",1).drawString("*",x+13,y+17);return}drawSuit(suit,x+10,y+15);strong(suitText(suit),x+sx,y+29,1)}function handStart(index,count,override){const maxStart=count>5?count-5:0;let start;if(override!==undefined&&override>=0)start=override;else start=index>2?index-2:0;if(start>maxStart)start=maxStart;return start}function handCard(card,x,y,selected){const rankValue=cardRank(card),suit=cardSuit(card);h.setColor(3).drawRect(x,y,x+54,y+53).drawRect(x+1,y+1,x+53,y+52);bold(rankText(rankValue),x+5,y+4,2);if(rankValue===14){spacedBold("JOKER",x+27,y+28,1,0)}else{drawSuit(suit,x+21,y+22);h.setFont("6x8",2).drawString(suitText(suit),x+39,y+33)}if(selected)selector(x-3,y-3,x+57,y+56)}function caravan(cards,x,y,selected){let i,start,drawX,value=total(cards);h.setColor(3).drawRect(x,y,x+132,y+69);spacedBold(String(value),x+120,y+6,2,1);if(value>=21&&value<=26)spacedBold("SOLD",x+66,y+8,1,0);else if(value>26)spacedBold("BUST",x+66,y+8,1,0);start=cards.length>4?cards.length-4:0;drawX=x+5;for(i=start;i<cards.length;i++){miniCard(cards[i],drawX,y+20);drawX+=31}if(!cards.length)spacedBold("EMPTY",x+66,y+35,1,0);if(selected)selector(x-3,y-3,x+135,y+72)}function hand(state){let i,start=handStart(state.handIndex,state.playerHand.length,state.handStartOverride),end=Math.min(start+5,state.playerHand.length),x=14;h.setColor(0).fillRect(0,215,479,279).setColor(3);for(i=start;i<end;i++){handCard(state.playerHand[i],x,223,i===state.handIndex);x+=91}}function eraseSelector(x1,y1,x2,y2){h.setColor(0).drawRect(x1,y1,x2,y2).drawRect(x1+1,y1+1,x2-1,y2-1).setColor(3)}function redrawHandSelection(state,previous){const count=state.playerHand.length,oldStart=handStart(previous,count,state.handStartOverride),newStart=handStart(state.handIndex,count,state.handStartOverride);let x;if(oldStart!==newStart){hand(state);redrawHandScroller(state);return}if(previous>=oldStart&&previous<oldStart+5&&previous<count){x=14+(previous-oldStart)*91;eraseSelector(x-3,220,x+57,279)}if(state.handIndex>=newStart&&state.handIndex<newStart+5&&state.handIndex<count){x=14+(state.handIndex-newStart)*91;selector(x-3,220,x+57,279)}redrawHandScroller(state)}function redrawTargetSelection(state,previous){let x;if(previous>=0&&previous<3){x=laneX[previous];eraseSelector(x-3,139,x+135,214)}if(state.targetIndex>=0&&state.targetIndex<3){x=laneX[state.targetIndex];selector(x-3,139,x+135,214)}}function handScroller(state){const count=state.playerHand.length,trackX1=178,trackX2=302,trackY=300,thumbWidth=28,travel=trackX2-trackX1-thumbWidth+1;let thumbX;h.setColor(3).drawLine(trackX1,trackY,trackX2,trackY).drawLine(trackX1,trackY-2,trackX1,trackY+2).drawLine(trackX2,trackY-2,trackX2,trackY+2);if(count<2)thumbX=trackX1+Math.floor(travel/2);else thumbX=trackX1+Math.floor(travel*state.handIndex/(count-1));h.fillRect(thumbX,trackY-3,thumbX+thumbWidth-1,trackY+3)}function redrawHandScroller(state){h.setColor(0).fillRect(174,296,306,304).setColor(3);handScroller(state)}function actionRow(text,row,selected){const y=108+row*30;h.setColor(0).fillRect(148,y-3,332,y+20).setColor(3).setFontAlign(0,-1);spacedBold(text,240,y,2,0);if(selected)h.drawRect(152,y-3,328,y+20);h.setFontAlign(-1,-1)}function drawActionMenu(state){h.setColor(0).fillRect(122,70,358,208).setColor(3).drawRect(122,70,358,208).drawRect(124,72,356,206).setFontAlign(0,-1);spacedBold("CARD ACTION",240,80,1,0);actionRow("Play Card",0,state.actionSelection===0);actionRow("Discard Card",1,state.actionSelection===1);actionRow("Back",2,state.actionSelection===2)}function redrawActionSelection(state,previous){actionRow(previous===0?"Play Card":previous===1?"Discard Card":"Back",previous,0);actionRow(state.actionSelection===0?"Play Card":state.actionSelection===1?"Discard Card":"Back",state.actionSelection,1)}function redrawStatusTitle(state){h.setColor(0).fillRect(16,0,464,21).setColor(3);spacedBold(state.message,240,4,2,0);h.drawLine(16,22,464,22)}function footer(state){const totalLabel="Total Cards = "+state.totalCards;h.setColor(0).fillRect(0,282,479,319).setColor(3).drawLine(16,282,464,282);spacedBold("HAND",240,285,1,0);handScroller(state);spacedBold(totalLabel,456,286,1,1);spacedBold("L1 caravan/play",22,300,1,-1);spacedBold("R1 Scroll",456,300,1,1)}function draw(state){let lane;h.clear().setColor(3).drawLine(16,22,464,22);spacedBold(state.message,240,4,2,0);spacedBold(state.opponent,22,26,2,-1);spacedBold("YOU",22,119,2,-1);spacedBold("CPU CARAVANS",360,28,1,-1);spacedBold("YOUR CARAVANS",350,122,1,-1);for(lane=0;lane<3;lane++){caravan(state.cpuCaravans[lane],laneX[lane],48,0);caravan(state.playerCaravans[lane],laneX[lane],142,!state.cpuTurn&&lane===state.targetIndex)}hand(state);footer(state);if(state.actionMenuOpen)drawActionMenu(state)}return{draw:draw,redrawHandSelection:redrawHandSelection,redrawTargetSelection:redrawTargetSelection,redrawFooter:footer,redrawStatusTitle:redrawStatusTitle,drawActionMenu:drawActionMenu,redrawActionSelection:redrawActionSelection,remove:function(){suitImages=[]}}});